(async()=>{
  const E=window.__echoes; const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const evs=[], trace=[];
  const KEEP=['run_start','room_enter','room_cleared','reward_offer','draft_taken','draft_declined','path_offer','path_chosen','room_transition','shop_open','shop_purchase','currency_denied','shop_close','boss_spawn','boss_adds','boss_seal_start','boss_seal_break','run_end','run_wiped'];
  for (const t of KEEP) E.on(t,(ev)=>evs.push(t+' t'+ev.tick+' '+JSON.stringify(Object.keys(ev).filter(k=>k!=='tick'&&k!=='type').reduce((o,k)=>{o[k]=ev[k];return o;},{}))));
  E.cmd('startRun');
  let guard=0,dwell=0,lastRoom=0;
  while(guard++<1400){
    const v=E.cmd('runState');
    if(v.phase==='victory'||v.phase==='defeat'){ trace.push('END '+v.phase+' rooms='+v.summary.rooms+'/8 combat='+v.summary.combatRooms+' glint='+v.summary.glint); break; }
    if(v.phase==='combat'){
      if(v.room!==lastRoom){ lastRoom=v.room; dwell=0; trace.push('ROOM '+v.room+' '+v.mode); }
      dwell++;
      E.cmd('killAllEnemies');
      if(v.mode==='defend'&&dwell>18) E.cmd('clearRoom');
    }
    else if(v.phase==='reward'){ trace.push('REWARD r'+v.room+' promised='+v.reward.promised+' -> '+v.reward.type+':'+v.reward.id+(v.reward.substituted?' SUBSTITUTED':'')+' free='+v.reward.freeSkillSlots); E.cmd('draftTake'); }
    else if(v.phase==='path'){ trace.push('PATH r'+v.room+' doors=['+v.path.options.map(o=>o.win+'/'+o.reward).join(', ')+'] free='+v.path.freeSkillSlots); E.cmd('pathChoose',0); }
    else if(v.phase==='shop'){ trace.push('SHOP wallet='+v.wallet+' stock='+v.shop.stock.map(s=>s.node+'@'+s.price+(s.affordable?'':' UNAFFORDABLE')).join(', ')); E.cmd('shopAdvance'); }
    await sleep(70);
  }
  const ring=E.events;
  return { trace, evs,
    byType:{ room_enter:ring.filter(e=>e.type==='room_enter').length, reward_offer:ring.filter(e=>e.type==='reward_offer').length, draft_taken:ring.filter(e=>e.type==='draft_taken').length, path_chosen:ring.filter(e=>e.type==='path_chosen').length },
    fps:E.fps };
})()
